#include "opensim/server/seed_caps.hpp"
#include "opensim/network/osd_json.hpp"
#include "opensim/network/osd_value.hpp"
#include <iostream>
using namespace opensim;
std::string hex(std::string_view s){std::string r;for(unsigned char c:s){r+="0123456789abcdef"[c>>4];r+="0123456789abcdef"[c&15];}return r;}
std::string unhex(std::string_view s){std::string r;for(std::size_t i=0;i<s.size();i+=2)r+=static_cast<char>(std::stoi(std::string(s.substr(i,2)),nullptr,16));return r;}
struct Context{network::Value command;std::string trace;void log(const std::string& s){trace+=s+";";if(network::osd_string(command.get("failure"))==s)throw std::runtime_error("injected");}};
struct Event:services::CapabilityActivation{Context& c;bool active=false;explicit Event(Context& ctx):c(ctx){}void reset()override{active=false;}void set()override{active=true;}bool wait(int ms)override{c.log("wait"+std::to_string(ms));return active;}void dispose()override{}};
struct Listener:services::CapabilityRuntimeListener{bool use_ssl()const override{return false;}std::uint32_t port()const override{return 8080;}std::uint32_t ssl_port()const override{return 9443;}std::optional<std::string> ssl_common_name()const override{return "host";}void add_stream(const std::shared_ptr<server::CapabilityStreamHandler>&)override{}void remove_stream(const std::string&,const std::optional<std::string>&)override{}void add_simple(const std::shared_ptr<server::CapabilitySimpleHandler>&)override{}void remove_simple(const std::optional<std::string>&)override{}void add_poll(const std::shared_ptr<services::CapabilityPollHandler>&)override{}void remove_poll(const std::optional<std::string>&)override{}};
struct Handler:server::CapabilityStreamHandler{std::optional<std::string> path()const override{return "/local<&'\"";}std::string method()const override{return "POST";}network::HttpResponse handle(const network::HttpRequest&)override{return {};}};
struct Backend:server::SeedCapsBackend{Context& c;services::Caps& object;Backend(Context& ctx,services::Caps& cap):c(ctx),object(cap){}services::Caps& caps()override{return object;}std::optional<std::string> region_name()const override{return "Region";}bool check_client(const framework::Uuid& id,const network::HttpRequest& r)override{c.log("check:"+id.str()+":"+r.remote_ip+":"+std::to_string(r.remote_port));return !c.command.contains("allow")||network::osd_boolean(c.command.get("allow"));}std::uint32_t region_size_x()const override{c.log("x");return c.command.contains("x")?static_cast<std::uint32_t>(network::osd_unsigned(c.command.get("x"))):256;}std::uint32_t region_size_y()const override{c.log("y");return c.command.contains("y")?static_cast<std::uint32_t>(network::osd_unsigned(c.command.get("y"))):256;}void debug(const std::string& s)override{c.log("debug:"+hex(s));}void warn(const std::string& s)override{c.log("warn:"+hex(s));}std::optional<services::Caps::Requested> deserialize(const network::HttpRequest& r)override{c.log("input");return server::deserialize_seed_caps(r.body);}};
int main(){std::string line;while(std::getline(std::cin,line)){Context ctx{network::parse_osd_json(unhex(line))};auto listener=std::make_shared<Listener>();auto activation=std::make_shared<Event>(ctx);services::Caps caps(listener,"host",9000,"seed",framework::Uuid("00000000-0000-0000-0000-000000000001"),"Region",[listener]{return listener;},activation);for(const auto& name:ctx.command.get("caps").array)caps.register_handler(network::osd_string(name),std::make_shared<Handler>());auto poll=std::make_shared<services::CapabilityPollHandler>();poll->url="/poll";caps.register_poll("Poll",poll);caps.register_external("External","https://external/cap?a=1&b=2");if(!ctx.command.contains("active")||network::osd_boolean(ctx.command.get("active")))caps.activate();caps.flags=static_cast<std::uint32_t>(network::osd_unsigned(ctx.command.get("flags")));Backend backend(ctx,caps);server::SeedCapsHandler handler(backend);network::HttpRequest request;request.method=ctx.command.contains("method")?network::osd_string(ctx.command.get("method")):"POST";request.content_type=ctx.command.contains("type")?network::osd_string(ctx.command.get("type")):"application/llsd+xml";request.body=unhex(network::osd_string(ctx.command.get("xml")));request.remote_ip="127.0.0.1";request.remote_port=1234;network::HttpResponse response;response.status=201;response.content_type="initial";response.body="initial";std::string result="OK";try{handler.process_request(request,response);}catch(const std::exception&){result="EX";}std::string parsed;try{auto names=server::deserialize_seed_caps(request.body);if(!names)parsed="NULL";else for(const auto& n:*names)parsed+=(n?hex(*n):"-")+",";}catch(const std::exception&){parsed="EX";}std::cout<<result<<"|"<<response.status<<"|"<<hex(response.body)<<"|"<<caps.flags<<"|"<<response.headers["Retry-After"]<<"|"<<hex(response.content_type)<<"|"<<hex(ctx.trace)<<"|"<<parsed<<"\n";}}
